package com.zenix.musicplayer;
import org.json.*;
import java.util.*;
final class SpaceFeatureFormat {
    static JSONObject clean(JSONObject raw)throws Exception{
        if(raw==null)raw=new JSONObject();if(raw.toString().length()>2*1024*1024)throw new Exception("空间资料过大");
        JSONObject p=raw.optJSONObject("roaming");if(p==null)p=new JSONObject();String scope=p.optString("scope","all"),motion=raw.optString("motion","full");if(!Set.of("all","saved","playlist").contains(scope))scope="all";if(!Set.of("full","light","reduced").contains(motion))motion="full";
        JSONArray excluded=new JSONArray(),rows=p.optJSONArray("excluded");if(rows!=null)for(int i=0;i<rows.length()&&i<500;i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&Set.of("song","version","artist").contains(row.optString("kind")))excluded.put(Json.obj("id",text(row,"id",100),"kind",row.optString("kind"),"effect",row.optString("effect").equals("reduce")?"reduce":"exclude","key",identifier(row,"key",24000),"label",text(row,"label",500)));}
        JSONArray zones=new JSONArray();rows=raw.optJSONArray("zones");if(rows!=null)for(int i=0;i<rows.length()&&i<20;i++){JSONObject row=rows.getJSONObject(i);JSONArray ids=new JSONArray(),values=row.optJSONArray("trackIds");Set<String> seen=new HashSet<>();if(values!=null)for(int j=0;j<values.length()&&j<1000;j++){String id=values.optString(j);if(id.length()<=24000&&seen.add(id))ids.put(id);}zones.put(Json.obj("id",text(row,"id",100),"name",text(row,"name",100),"trackIds",ids));}
        JSONArray bookmarks=new JSONArray();rows=raw.optJSONArray("bookmarks");if(rows!=null)for(int i=0;i<rows.length()&&i<30;i++){JSONObject row=rows.getJSONObject(i),camera=row.optJSONObject("camera");if(camera==null)camera=new JSONObject();JSONArray tracks=new JSONArray(),values=row.optJSONArray("tracks");if(values!=null)for(int j=0;j<values.length()&&j<500;j++){JSONObject song=values.getJSONObject(j);tracks.put(Json.obj("id",identifier(song,"id",24000),"title",text(song,"title",500),"artist",text(song,"artist",500),"album",text(song,"album",500),"source",song.optString("source","custom"),"providerId",text(song,"providerId",300),"remoteId",identifier(song,"remoteId",20000),"duration",finite(song.optDouble("duration",0),0,86400),"path","","audioUrl",""));}bookmarks.put(Json.obj("id",text(row,"id",100),"name",text(row,"name",100),"selectedId",identifier(row,"selectedId",24000),"camera",Json.obj("x",finite(camera.optDouble("x",0),-1e6,1e6),"y",finite(camera.optDouble("y",0),-1e6,1e6),"scale",finite(camera.optDouble("scale",1),.4,2.5)),"tracks",tracks));}
        return Json.obj("schema",1,"revision",Math.max(0,raw.optLong("revision")),"motion",motion,"bookmarks",bookmarks,"zones",zones,"roaming",Json.obj("scope",scope,"playlistId",text(p,"playlistId",300),"discovery",finite(p.optDouble("discovery",.5),0,1),"artistGap",Math.max(0,Math.min(5,p.optInt("artistGap"))),"excluded",excluded));
    }
    private static double finite(double value,double min,double max){return Double.isFinite(value)?Math.max(min,Math.min(max,value)):min;}
    private static String text(JSONObject row,String key,int limit){String value=row.optString(key,"");return value.substring(0,Math.min(value.length(),limit));}
    private static String identifier(JSONObject value,String key,int limit)throws Exception{String text=value.optString(key);if(text.length()>limit)throw new Exception("歌曲引用过长");return text;}
}
